sys_variable_value.value:
(function execute(inputs, outputs) {


  try {
    // Verifica se a entrada é uma string válida
    if (!inputs.stringConverter) {
        outputs.error = "Nenhum dado foi fornecido para conversão.";
        return;
    }

    // Converte a string em um objeto JavaScript (espera-se que seja um array)
    var parsedInput = JSON.parse(inputs.stringConverter);

    // Garante que a estrutura esperada é um array
    if (!Array.isArray(parsedInput)) {
        outputs.error = "Estrutura de dados inválida. Esperado um array.";
        return;
    }

   
    var resultArray = [];

    // Processa cada item do array para criar o objeto no formato desejado
    parsedInput.forEach(function (dadosLuc) {
        if (dadosLuc) {
            var obj = {
                lucAtual: dadosLuc.luc_atual_v2 || null, // Extrai 'luc_atual_v2'
                areaAnterior_m: dadosLuc.area_anterior_m || null // Extrai 'area_anterior_m'
            };
            resultArray.push(obj); // Adiciona ao array de resultados
        }
    });

    // Retorna o array processado como saída
    outputs.string = JSON.stringify(resultArray); // String JSON do resultado
    outputs.arrayobj = resultArray;              // Array do resultado
    outputs.obj = resultArray;                   // Objeto com os resultados

} catch (error) {
    // Trata erros de parsing ou outros imprevistos
    outputs.error = "Erro ao processar os dados: " + error.message;
}


})(inputs, outputs);

